CREATE POLICY qard_reload_receipts_service ON public.qard_reload_receipts FOR ALL TO service_role USING (true) WITH CHECK (true);
ALTER POLICY terminal_requests_read ON public.terminal_agent_requests USING (auth.uid() IS NOT NULL AND (user_id=auth.uid() OR (public.is_admin() AND public.has_role(auth.uid(),'admin'))));
ALTER POLICY terminal_permissions_read ON public.terminal_permissions USING (auth.uid() IS NOT NULL AND (user_id=auth.uid() OR (public.is_admin() AND public.has_role(auth.uid(),'admin'))));
ALTER POLICY terminal_operations_read ON public.terminal_operations USING (auth.uid() IS NOT NULL AND (merchant_user_id=auth.uid() OR target_user_id=auth.uid() OR (public.is_admin() AND public.has_role(auth.uid(),'admin'))));
ALTER POLICY terminal_catalog_read ON public.terminal_catalog USING (auth.uid() IS NOT NULL);
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.terminal_reload(text,numeric,uuid)'::regprocedure) INTO def; def:=replace(def,'SELECT * INTO lim FROM public.qard_limite_recarga(target);','SELECT CASE WHEN i.estado=''moral_approved'' THEN NULL ELSE GREATEST(COALESCE(i.monthly_limit_udis,0)*COALESCE((SELECT valor_udi_mxn FROM public.pagos_config LIMIT 1),8.60)-public.qard_entradas_mes(target),0) END AS disponible INTO lim FROM public.qard_identidad i WHERE i.user_id=target;'); EXECUTE def; END; $$;
CREATE FUNCTION public.terminal_review_note(_id uuid,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.is_admin() AND public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Solo el administrador'; END IF; IF length(COALESCE(_note,''))>2000 THEN RAISE EXCEPTION 'Nota demasiado larga'; END IF; UPDATE public.terminal_agent_requests SET review_note=_note WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no encontrada'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.terminal_review_note(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.terminal_review_note(uuid,text) TO authenticated;